9	  checkPermission,
10	  PermissionType,
11	} from "modules/permissions/utils/checkPermission";
12	import { useCallback, useEffect, useRef, useState } from "react";
13	import { AppState, Image, Platform, StyleSheet } from "react-native";
14	import { useSafeAreaInsets } from "react-native-safe-area-context";
15	import { WebView, type WebViewMessageEvent } from "react-native-webview";
