19	const MESSAGE_BRIDGE_SCRIPT = `
20	            // Setup message bridge between Element Call and React Native
21	            (function() {
22	              console.log('Setting up React Native bridge...');
23	              
24	              // Store original postMessage
25	              const originalPostMessage = window.postMessage.bind(window);
26	              
27	              // Flag to prevent re-capturing injected messages
28	              let isInjecting = false;
29	              
30	              // Expose method for injecting messages without re-capture
31	              window.__rnInjectMessage = function(message) {
32	                isInjecting = true;
33	                try {
34	                  originalPostMessage(message, '*');
35	                } finally {
36	                  isInjecting = false;
37	                }
38	              };
39	
40	              // Override postMessage to intercept widget messages
41	              window.postMessage = function(message, targetOrigin) {
42	                // Don't capture messages that we're injecting from RN
43	                if (!isInjecting) {
44	                  try {
45	                    // Send to React Native if available
46	                    if (window.ReactNativeWebView) {
47	                      const messageStr = typeof message === 'string' 
48	                        ? message 
49	                        : JSON.stringify(message);
50	                      window.ReactNativeWebView.postMessage(messageStr);
51	                      console.log('Sent to RN:', messageStr);
52	                    }
53	                  } catch (e) {
54	                    console.error('Failed to send to RN:', e);
55	                  }
56	                }
57	                
58	                // Always call original for in-page communication
59	                try {
60	                  originalPostMessage(message, targetOrigin);
61	                } catch (e) {
62	                  console.error('Failed original postMessage:', e);
63	                }
64	              };
65	            
66	              console.log('React Native bridge ready');
67	            })();
68	            true; // Required for iOS          
69	  `;
