71	type ElementCallSessionProps = {
72	  roomId: string;
73	  roomName?: string;
74	};
75	
76	export const ElementCallSession = ({
77	  roomId,
78	  roomName,
79	}: ElementCallSessionProps) => {
80	  const insets = useSafeAreaInsets();
81	  const client = MatrixCore.instance;
82	  const room = client?.getRoom(roomId);
83	  const webViewRef = useRef<WebView>(null);
84	  const [callUrl, setCallUrl] = useState<string | null>(null);
85	  const [loading, setLoading] = useState(true);
86	  const [error, setError] = useState<string | null>(null);
87	  const isOffline = useAtomValue(NetworkAtoms.isOffline);
88	  const [hasWebViewIssue, setHasWebViewIssue] = useState(false);
89	  const messageLoopRef = useRef<boolean>(false);
90	  const messageLoopRunningRef = useRef<boolean>(false);
91	  const initializingRef = useRef<boolean>(false);
92	  const [isCallEnding, setIsCallEnding] = useState(false);
93	  const [hasMediaPermissions, setHasMediaPermissions] = useState(false);
94	
95	  useEffect(() => {
96	    initializeCall();
97	
98	    return () => {
99	      messageLoopRef.current = false;
100	      messageLoopRunningRef.current = false;
101	      initializingRef.current = false;
102	      void ElementCallService.cleanupDriver(roomId);
103	    };
104	  }, [roomId]);
105	
106	  useEffect(() => {
107	    if (Platform.OS !== "ios") return;
108	
109	    const removePipDebugListener = PictureInPictureService.subscribeDebugEvents(
110	      (payload) => {
111	        console.log("[ElementCallPiP][event]", payload);
112	      },
113	    );
114	
115	    PictureInPictureService.getDebugState()
116	      .then((state) => {
117	        console.log("[ElementCallPiP][initial-state]", state);
118	      })
119	      .catch((pipError) => {
120	        console.error("[ElementCallPiP][initial-state-error]", pipError);
121	      });
122	
123	    PictureInPictureService.setEnabled(true);
124	    PictureInPictureService.setActivePiPCall(roomId, roomName);
125	
126	    const appStateSubscription = AppState.addEventListener(
127	      "change",
128	      (nextState) => {
129	        if (nextState !== "inactive" && nextState !== "background") return;
130	
131	        PictureInPictureService.enterIfSupported().catch((pipError) => {
132	          console.error("Failed to enter iOS Picture-in-Picture:", pipError);
133	        });
134	      },
135	    );
136	
137	    return () => {
138	      removePipDebugListener();
139	      appStateSubscription?.remove();
140	      PictureInPictureService.stop().catch(() => undefined);
141	      PictureInPictureService.setEnabled(false);
142	    };
143	  }, [roomId, roomName]);
144	
145	  const initializeCall = async () => {
146	    if (initializingRef.current) {
147	      return;
148	    }
149	
150	    try {
151	      if (!client || !room) throw new Error("Client or room not available");
152	
153	      initializingRef.current = true;
154	      setLoading(true);
155	      setError(null);
156	
157	      const [cameraGranted, microphoneGranted] = await Promise.all([
158	        checkPermission(PermissionType.CAMERA),
159	        checkPermission(PermissionType.MICROPHONE),
160	      ]);
161	
162	      const permissionsGranted = cameraGranted && microphoneGranted;
163	      setHasMediaPermissions(permissionsGranted);
164	
165	      if (!permissionsGranted) {
166	        throw new Error(
167	          "Camera and microphone permissions are required for video calls",
168	        );
169	      }
170	
171	      const { url } = await ElementCallService.startCall(roomId, room, client);
172	
173	      setCallUrl(url);
174	
175	      setTimeout(() => {
176	        startMessageLoop();
177	      }, 1000);
178	
179	      setLoading(false);
180	    } catch (initError) {
181	      console.error("Failed to initialize call:", initError);
182	      setError(
183	        initError instanceof Error
184	          ? initError.message
185	          : "Failed to initialize call",
186	      );
187	      setLoading(false);
188	      initializingRef.current = false;
189	    }
190	  };
191	
192	  const startMessageLoop = () => {
193	    if (messageLoopRunningRef.current) return;
194	
195	    messageLoopRef.current = true;
196	    messageLoopRunningRef.current = true;
197	
198	    const runLoop = async () => {
199	      while (messageLoopRef.current) {
200	        try {
201	          const message =
202	            await ElementCallService.receiveMessagesFromWidget(roomId);
203	
204	          if (!message) break;
205	
206	          if (webViewRef.current) {
207	            const script = `
208	              try {
209	                if (window.__rnInjectMessage) {
210	                  window.__rnInjectMessage(${message});
211	                } else {
212	                  window.postMessage(${message}, '*');
213	                }
214	              } catch (e) {
215	                console.error('Failed to post message:', e);
216	              }
217	            `;
218	            webViewRef.current.injectJavaScript(script);
219	          }
220	
221	          await new Promise((resolve) => setTimeout(resolve, 10));
222	        } catch (loopError) {
223	          console.error("Error in message loop:", loopError);
224	          await new Promise((resolve) => setTimeout(resolve, 500));
225	        }
226	      }
227	
228	      messageLoopRunningRef.current = false;
229	    };
230	
231	    runLoop();
232	  };
233	
234	  const handleMinimize = useCallback(async () => {
235	    if (Platform.OS !== "ios") return;
236	
237	    PictureInPictureService.setActivePiPCall(roomId, roomName);
238	
239	    const didStartPromise = new Promise<void>((resolve) => {
240	      const timeout = setTimeout(() => {
241	        removeListener();
242	        resolve();
243	      }, 3000);
244	
245	      const removeListener = PictureInPictureService.subscribeDidStart(() => {
246	        clearTimeout(timeout);
247	        removeListener();
248	        resolve();
249	      });
250	    });
251	
252	    const started = await PictureInPictureService.enterIfSupported();
253	    if (!started) return;
254	
255	    await didStartPromise;
256	    CallOverlayService.minimizeActiveCall();
257	  }, [roomId, roomName]);
258	
259	  const closeCall = async () => {
260	    messageLoopRef.current = false;
261	    messageLoopRunningRef.current = false;
262	    await ElementCallService.cleanupDriver(roomId);
263	    PictureInPictureService.clearActivePiPCall();
264	    PictureInPictureService.setEnabled(false);
265	    CallOverlayService.clearActiveCall();
266	  };
267	
268	  const shouldShowFallbackClose = isOffline || hasWebViewIssue;
269	
270	  const handleWebViewMessage = async (event: WebViewMessageEvent) => {
271	    try {
272	      const messageData = event.nativeEvent.data;
273	
274	      const data = JSON.parse(messageData);
275	      const action = data?.action as string | undefined;
276	
277	      const isEndCallMessage =
278	        action === "im.vector.hangup" ||
279	        action === "hangup" ||
280	        action === "io.element.close";
281	
282	      if (isEndCallMessage) {
283	        setIsCallEnding(true);
284	        await closeCall();
285	      } else {
286	        await ElementCallService.sendMessageToWidget(roomId, messageData);
287	      }
288	    } catch (messageError) {
289	      console.error("Failed to handle WebView message:", messageError);
290	    }
291	  };
292	
293	  if (loading) {
294	    return (
295	      <Block
296	        absolute
297	        background={Colors.black}
298	        justify="center"
299	        align="center"
300	        width="100%"
301	        height="100%"
302	        zIndex={9999}
303	        paddings={{ paddingTop: insets.top + 40, paddingHorizontal: 20 }}
304	      >
305	        <Block flexDirection="row" justify="flex-end" width="100%">
306	          <Button.Outline onPress={closeCall} size="medium">
307	            <Text size={TextSize.small} color={Colors.white}>
308	              Close
309	            </Text>
310	          </Button.Outline>
311	        </Block>
312	        <Loading isFullScreen={false} />
313	      </Block>
314	    );
315	  }
316	
317	  if (error || !callUrl) {
318	    return (
319	      <Block
320	        absolute
321	        background={Colors.black}
322	        justify="space-between"
323	        align="center"
324	        width="100%"
325	        height="100%"
326	        zIndex={9999}
327	        paddings={{ paddingTop: insets.top + 40, paddingHorizontal: 20 }}
328	      >
329	        <Block flexDirection="row" justify="flex-end" width="100%" gap={60}>
330	          <Button.Outline onPress={closeCall} size="medium">
331	            <Text size={TextSize.small} color={Colors.white}>
332	              Close
333	            </Text>
334	          </Button.Outline>
335	        </Block>
336	        <Block margins="auto">
337	          <Text size={TextSize.medium} color={Colors.error}>
338	            {error || "Failed to load call"}
339	          </Text>
340	        </Block>
341	      </Block>
342	    );
343	  }
344	
345	  if (isCallEnding) {
346	    return (
347	      <Block
348	        align="center"
349	        justify="center"
350	        flex={1}
351	        background={Colors.black}
352	        paddings={24}
353	      >
354	        <Text size={TextSize.medium} color={Colors.white}>
355	          Call is ending...
356	        </Text>
357	      </Block>
358	    );
359	  }
360	
361	  return (
362	    <Block
363	      flex={1}
364	      background={Colors.black}
365	      paddings={{ paddingTop: insets.top }}
366	    >
367	      <Block
368	        flexDirection="row"
369	        align="center"
370	        justify="space-between"
371	        paddings={{ paddingHorizontal: 16, paddingVertical: 12 }}
372	        background={Colors.black}
373	        width="100%"
374	        gap={12}
375	      >
376	        {shouldShowFallbackClose ? (
377	          <Block>
378	            <Button.Wrapper onPress={closeCall}>
379	              <Block paddings={12}>
380	                <Text size={TextSize.small} color={Colors.white}>
381	                  Close
382	                </Text>
383	              </Block>
384	            </Button.Wrapper>
385	          </Block>
386	        ) : (
387	          <Block width={40} height={40} />
388	        )}
389	        <Block flex={1} flexDirection="row" justify="center" gap={12}>
390	          <Block align="center">
391	            {roomName && (
392	              <Text
393	                size={TextSize.large}
394	                numberOfLines={1}
395	                font="InstrumentSans-Semibold"
396	              >
397	                {roomName}
398	              </Text>
399	            )}
400	            <Text size={TextSize.small} color={Colors.white50}>
401	              Ongoing call
402	            </Text>
403	          </Block>
404	        </Block>
405	        {Platform.OS === "ios" && (
406	          <Block flexDirection="row" justify="flex-end">
407	            <Button.Wrapper onPress={handleMinimize}>
408	              <Block paddings={12}>
409	                <Image
410	                  width={24}
411	                  height={24}
412	                  source={require("assets/icons/arrows-in.png")}
413	                />
414	              </Block>
415	            </Button.Wrapper>
416	          </Block>
417	        )}
418	      </Block>
419	
420	      <Block flex={1}>
421	        <WebView
422	          ref={webViewRef}
423	          source={{ uri: callUrl }}
424	          style={styles.webview}
425	          onMessage={handleWebViewMessage}
426	          allowsInlineMediaPlayback
427	          mediaPlaybackRequiresUserAction={false}
428	          allowsLinkPreview
429	          javaScriptEnabled
430	          domStorageEnabled
431	          cacheEnabled
432	          originWhitelist={["*"]}
433	          mixedContentMode="always"
434	          thirdPartyCookiesEnabled
435	          sharedCookiesEnabled
436	          allowFileAccessFromFileURLs
437	          mediaCapturePermissionGrantType={
438	            hasMediaPermissions ? "grant" : "deny"
439	          }
440	          allowsPictureInPictureMediaPlayback
441	          startInLoadingState
442	          injectedJavaScriptBeforeContentLoaded={MESSAGE_BRIDGE_SCRIPT}
443	          renderLoading={() => <Loading />}
444	          onError={({ nativeEvent }) => {
445	            setHasWebViewIssue(true);
446	            console.error("WebView error:", nativeEvent);
447	          }}
448	          onHttpError={({ nativeEvent }) => {
449	            setHasWebViewIssue(true);
450	            console.error("WebView HTTP error:", nativeEvent);
451	          }}
452	          onLoad={() => {
453	            if (!isOffline) {
454	              setHasWebViewIssue(false);
455	            }
456	          }}
457	          userAgent={
458	            Platform.OS === "ios"
459	              ? "Mozilla/5.0 (iPhone; CPU iPhone OS 14_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/14.0 Mobile/15E148 Safari/604.1"
460	              : "Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.120 Mobile Safari/537.36"
461	          }
462	        />
463	      </Block>
464	    </Block>
465	  );
466	};
467	
