1	import { useAtomValue, useSetAtom } from 'jotai';
2	import { CallAtoms } from 'modules/call/jotai';
3	import { CallKitService } from 'modules/call/service/CallKitService';
4	import { CallOverlayService } from 'modules/call/service/CallOverlayService';
5	import { ElementCallService } from 'modules/call/service/ElementCallService';
6	import { PictureInPictureService } from 'modules/call/service/PictureInPictureService';
7	import { MatrixAtoms } from 'modules/matrix-client/jotai';
8	import { MatrixCore } from 'modules/matrix-client/services/MatrixCore';
9	import { RoomService } from 'modules/room/service/RoomService';
10	import { useEffect, useRef } from 'react';
11	import { Platform } from 'react-native';
12	
13	/** Provider that initializes CallKit on iOS and monitors rooms for incoming calls via sync. */
14	export const CallKitProvider = () => {
15	  const roomList = useAtomValue(MatrixAtoms.roomList);
16	  const setHasActiveCall = useSetAtom(CallAtoms.hasActiveCall);
17	  const prevActiveCallRoomIds = useRef<Set<string>>(new Set());
18	
19	  // Initialize CallKit
20	  useEffect(() => {
21	    if (Platform.OS !== 'ios') return;
22	
23	    CallKitService.setup();
24	  }, []);
25	
26	  // Monitor room list for active calls (foreground detection without push)
27	  useEffect(() => {
28	    if (Platform.OS !== 'ios' || roomList.length === 0) return;
29	
30	    const currentActiveCallRoomIds = new Set<string>();
31	
32	    for (const room of roomList) {
33	      if (!room.hasActiveRoomCall()) return;
34	      currentActiveCallRoomIds.add(room.id());
35	    }
36	
37	    // Detect newly active calls (rooms that weren't active before)
38	    for (const roomId of currentActiveCallRoomIds) {
39	      if (prevActiveCallRoomIds.current.has(roomId)) continue;
40	
41	      // Don't show CallKit if we initiated the call ourselves
42	      if (ElementCallService.getActiveCallRoomId() === roomId) continue;
43	
44	      // Don't show if already ringing for this room (e.g. from push)
45	      if (CallKitService.isRingingForRoom(roomId)) continue;
46	
47	      // Get room info for display
48	      const roomInfo = RoomService.getRoomInfo(roomId);
49	      const roomName = roomInfo?.displayName() ?? 'Unknown Room';
50	      const currentUserId = MatrixCore.instance?.userId();
51	
52	      // Don't ring for own calls
53	      if (!currentUserId) continue;
54	
55	      CallKitService.displayIncomingCall({
56	        roomId,
57	        roomName,
58	        senderDisplayName: roomName,
59	      });
60	    }
61	
62	    prevActiveCallRoomIds.current = currentActiveCallRoomIds;
63	  }, [roomList]);
64	
65	  // Keep a single global call state in sync for UI consumers.
66	  useEffect(() => {
67	    const syncGlobalActiveCall = () => {
68	      setHasActiveCall(
69	        !!CallOverlayService.getActiveCall() ||
70	          ElementCallService.hasActiveCall(),
71	      );
72	    };
73	
74	    syncGlobalActiveCall();
75	
76	    const removeOverlayListener = CallOverlayService.subscribe(() => {
77	      syncGlobalActiveCall();
78	    });
79	    const removeElementCallListener =
80	      ElementCallService.subscribeToActiveCallState(() => {
81	        syncGlobalActiveCall();
82	      });
83	
84	    return () => {
85	      removeOverlayListener();
86	      removeElementCallListener();
87	    };
88	  }, [setHasActiveCall]);
89	
90	  // Handle in-app PiP restore and stop events
91	  useEffect(() => {
92	    if (Platform.OS !== 'ios') return;
93	
94	    const removeRestoreListener =
95	      PictureInPictureService.subscribeRestoreRequested(() => {
96	        console.log('[PiP] restoreRequested event received');
97	        const call = PictureInPictureService.getActivePiPCall();
98	        console.log('[PiP] activePiPCall:', call);
99	
100	        if (call) {
101	          console.log('[PiP] restoring active call overlay');
102	          CallOverlayService.openCall(call.roomId, call.roomName);
103	          PictureInPictureService.clearActivePiPCall();
104	        } else {
105	          CallOverlayService.showActiveCall();
106	        }
107	
108	        // Always notify native that UI restore is complete
109	        PictureInPictureService.notifyRestoreComplete();
110	      });
111	
112	    const removeStopListener = PictureInPictureService.subscribeDidStop(
113	      payload => {
114	        console.log('[PiP] didStop event received:', payload);
115	        const call = PictureInPictureService.getActivePiPCall();
116	
117	        if (payload.isRestoring) {
118	          // Fallback: if restoreRequested didn't navigate, do it here
119	          if (call) {
120	            console.log(
121	              '[PiP] didStop fallback: restoring active call overlay',
122	            );
123	            CallOverlayService.openCall(call.roomId, call.roomName);
124	            PictureInPictureService.clearActivePiPCall();
125	          } else {
126	            CallOverlayService.showActiveCall();
127	          }
128	          return;
129	        }
130	
131	        if (!call) {
132	          const activeOverlayCall = CallOverlayService.getActiveCall();
133	          if (!activeOverlayCall) return;
134	          console.log('[PiP] PiP closed, cleaning up active overlay call');
135	          ElementCallService.cleanupDriver(activeOverlayCall.roomId);
136	          PictureInPictureService.setEnabled(false);
137	          CallOverlayService.clearActiveCall();
138	          return;
139	        }
140	
141	        // PiP closed without restore — clean up the call
142	        console.log('[PiP] PiP closed, cleaning up call');
143	        ElementCallService.cleanupDriver(call.roomId);
144	        PictureInPictureService.clearActivePiPCall();
145	        PictureInPictureService.setEnabled(false);
146	        CallOverlayService.clearActiveCall();
147	      },
148	    );
149	
150	    return () => {
151	      removeRestoreListener();
152	      removeStopListener();
153	    };
154	  }, []);
155	
156	  return <></>;
157	};
