206	      clearTimeout(timeout);
207	      this.ringTimeouts.delete(callUUID);
208	    }
209	
210	    // CRITICAL WORKAROUND: CallKit takes exclusive audio control which
211	    // breaks WebView-based audio/video. We must end the CallKit session
212	    // before opening Element Call WebView.
213	    // We use endCall() (not reportEndCallWithUUID) so the call is properly
214	    // recorded as "answered" in iPhone's Phone recents, not as "missed".
