236	    this.activeCallMap.delete(callUUID);
237	  }
238	
239	  private static async handleEndCall(event: {
240	    callUUID?: string;
241	    uuid?: string;
242	  }) {
243	    const callUUID = this.extractCallUUID(event);
244	    if (!callUUID) return;
245	
246	    // If we ended this call ourselves (after answering), just clean up the flag
247	    if (this.selfEndingCalls.has(callUUID)) {
248	      this.selfEndingCalls.delete(callUUID);
249	      return;
250	    }
251	
252	    const callInfo = this.activeCallMap.get(callUUID);
253	
254	    // Clear ring timeout
255	    const timeout = this.ringTimeouts.get(callUUID);
256	    if (timeout) {
257	      clearTimeout(timeout);
258	      this.ringTimeouts.delete(callUUID);
259	    }
260	
261	    if (callInfo) {
262	      this.activeCallMap.delete(callUUID);
263	      return;
264	    }
265	
266	    // Cold-start decline: JS has no activeCallMap entry, but native pending call
267	    // data may still exist from the VoIP push. Clear it to avoid stale redirects.
268	    await this.clearNativePendingCall();
269	  }
270	
271	  private static registerEventListeners() {
272	    // User answered the call from CallKit UI
273	    RNCallKeep.addEventListener("answerCall", async (event) => {
274	      await this.handleAnswerCall(event);
275	    });
276	
277	    // User declined the call from CallKit UI (or call ended by us after answer)
278	    RNCallKeep.addEventListener("endCall", async (event) => {
279	      await this.handleEndCall(event);
280	    });
281	
282	    // Replay events that occurred before JS listeners were registered.
283	    // This is crucial for cold launches from CallKit where answer/end actions
284	    // can arrive before React Native initializes.
285	    RNCallKeep.addEventListener(
286	      "didLoadWithEvents",
287	      async (payload: unknown) => {
288	        const bufferedPayload = payload as
289	          | CallKeepBufferedEvent[]
290	          | { events?: CallKeepBufferedEvent[] };
291	        const events = Array.isArray(bufferedPayload)
292	          ? bufferedPayload
293	          : bufferedPayload.events;
294	
295	        if (!Array.isArray(events)) return;
296	
297	        for (const event of events) {
298	          const data = event?.data ?? {};
299	          if (event?.name === "RNCallKeepPerformAnswerCallAction") {
300	            await this.handleAnswerCall(data);
301	            continue;
302	          }
303	          if (event?.name === "RNCallKeepPerformEndCallAction") {
304	            await this.handleEndCall(data);
305	          }
306	        }
307	      },
308	    );
309	
310	    // User tapped a call entry in iPhone's Phone recents to call back
311	    RNCallKeep.addEventListener(
312	      "didReceiveStartCallAction",
313	      ({ handle }: { handle: string }) => {
314	        if (!handle) return;
315	        CallOverlayService.openCall(handle);
316	
317	        // End the outgoing CallKit session since Element Call WebView handles it
318	        RNCallKeep.endAllCalls();
319	      },
320	    );
321	  }
322	}
