130	        if (CallKitService.isRingingForRoom(data.room_id)) return;
131	        const roomName = RoomService.getRoomInfo(data.room_id)?.displayName();
132	        CallKitService.displayIncomingCall({
133	          roomId: data.room_id,
134	          roomName: roomName || data.room_name || senderName,
135	          senderDisplayName: senderName,
136	        });
137	        return;
138	      }
