7	 *
8	 * Flow:
9	 *  PKPushRegistry (native) → VoIPPushModule emits "voIPPushTokenUpdated"
10	 *  → this service registers the token as a VoIP pusher with the Matrix homeserver
11	 *  → Sygnal uses the VoIP APNs certificate to wake the app even when killed
12	 */
13	export const VoIPPushService = {
14	  setup() {
15	    if (Platform.OS !== "ios") return;
16	
17	    const { VoIPPushModule } = NativeModules;
18	    if (!VoIPPushModule) return;
19	
20	    const emitter = new NativeEventEmitter(VoIPPushModule);
21	
22	    emitter.addListener("voIPPushTokenUpdated", async (token: string) => {
23	      if (!token || !MatrixCore.instance) return;
24	      try {
25	        await MatrixNotificationService.setVoIPPusher(token);
26	      } catch (error) {
27	        console.error("[VoIP] Failed to register VoIP pusher:", error);
28	      }
29	    });
30	  },
31	};
